    "stemRaw": "023.女性，42岁撞伤后胸痛、呼吸困难、咯血2小时\n一、初步诊\n患者两小时前在乘坐高速行驶的汽车时，因紧急刹车，右胸撞击在汽车的铁杆上，\n①右侧张\n②右侧主\n当即感到右前胸疼痛难忍，严重呼吸困难，伴咯血数口，随即送来医院既往体健，\n③休克\n查体：T37.0℃，P120次/分，R30次/分，BP90/60mmHg神志清楚，口唇发细，\n二、诊断依\n气管明显向左侧偏移右胸廊稍隆起，皮肤瘀斑，触痛明显，颈、胸部可触及\n三、鉴别诊\n广泛皮下气肿，但无骨摩擦感，语颤消失，叩诊呈鼓音，呼吸音消失心界不大，\n①开放\n②血胸\n心率120次/分，律齐，未闻及杂音腹部平软，无压痛反跳痛，肝脾肋下未触及，肠\n鸣音正常四肢活动正常，病理反射未引出\n③肋骨\n辅助检查：胸部×线片示胸部皮下气肿明显，右肺被压缩于肺门并呈“坠落征\"，\n四、进一步\n纵明显左移、肋骨未见骨折\n①胸腔\n②病情平\n五、治疗原\n①立即\n②使用\n③镇痛\n④保持\n开胸",
