    "stemRaw": "005.男，67岁左侧肢体无力、麻木3天\n一、初步诊\n患者于3天前无明显诱因逐渐出现左侧肢体无力，无法行走，左手无法持物，伴麻木\n右侧大脑\n5分，未\n感、言语不清，无头晕、头痛，无恶心、呕吐、无视物模糊，无饮水呛咳1天前上述\n症状无缓解，并出现饮水呛咳、左侧口角流涎，口角向右歪斜，来急诊就诊查头颅\n二、诊断依\nCT提示右侧顶叶及右侧基底节－放射冠区多发低密度灶否认其他病史饮酒30余\n三、鉴别诊\n年，目前已戒酒，吸烟30余年，每天约3包\n1）脑栓塞\n查体：T36.5℃C，P67次/分，R18次/分，BP122/69mmHg神志清楚，精神可，双肺呼\n2）脑出血\n吸音清，未闻及干湿性啰音心率67次/分，律齐，各瓣膜听诊区未闻及杂音腹软，\n3）脑肿瘤\n肝脾肋下未触及，肠鸣音正常专科查体：左侧中枢性面瘫，伸舌左偏，左上肢肌力2\n四、进一步\n级，左下肢肌力3级，右侧肢体肌力5级，左侧偏身感觉减退，左侧Babinski征\n1)头颅M\n2）头颅C\n3）血常规\n头颅CT：右侧低密度影\n4）心电图\n5）经颅多\n五、治疗原\n1）抗血小\n2）维持生\n3）预防控\n4）脑保护\n5）戒烟，",
