    "stem": "006.男性，40岁突发头痛、呕吐伴神志模糊1小时\n患者1小时前聚餐饮酒后突感剧烈枕顶部炸裂样痛，伴恶心呕吐、面色苍白、全身冷\n蛛网膜下\n汗，呕吐呈喷射状，之后很快出现神志模糊，就近急诊就诊患者既往体健，家属否认\n患者有头痛、高血压史，吸烟10余年，20支/天，偶饮酒无遗传性疾病家族史\n查体：T36.1°C，P82次/分，R24次/分，BP140/90mmHg，体型肥胖，被动体位，查\n体不合作双肺呼吸音清，未闻及干湿性啰音心率82次/分，律齐，各瓣膜听诊区未\n闻及杂音腹平软，肝脾肋下未触及专科查体：浅昏迷，双侧瞳孔等大等圆，直径约\n2.5mm，直接和间接对光反射存在但略迟钝，双侧眼球向左凝视双侧腱反射减弱，颈\n急诊头颅CT：环池高密度影\n3）头顾C\n维持生\n保持大\n24-72",
